-- What tests/pg_dump.rs makes a database of before it runs pg_dump on it: every kind of object pg_dump writes
-- (schemas, enum types, sequences, identity, serial and generated columns, defaults, checks, foreign keys, indexes, views,
-- a materialized view, functions, a procedure, a trigger, a collation and collated columns), with rows. It runs on Postgres as it is written.
create schema app;
create type app.status as enum ('new', 'open', 'done');
create type mood as enum ('sad', 'ok');
create sequence app.ticket_no start 1000 increment 5;
create table app.accounts (
  id bigserial primary key,
  code varchar(12) not null unique,
  balance numeric(12,2) not null default 0,
  ratio double precision default 1.5,
  active boolean not null default true,
  opened date default '2020-01-02',
  seen timestamptz,
  tags text[] default '{}',
  status app.status default 'new',
  note text default 'none'
);
create table app.tickets (
  id int generated by default as identity primary key,
  no bigint default nextval('app.ticket_no'),
  account_id bigint not null references app.accounts(id) on delete cascade,
  title text not null,
  body text,
  mood mood,
  check (length(title) > 2)
);
create table app.numbered (n int generated always as identity (start with 10 increment by 5 maxvalue 1000), label text);
create table app.badges (id int primary key, code varchar(12) references app.accounts (code) on update cascade on delete set null);
create table app.files (id int primary key, name text, body bytea not null default '\x00', digest bytea unique);
create table app.priced (net numeric(10,2) not null, tax numeric(10,2) not null default 0, gross numeric(10,2) generated always as (net + tax) stored);
create collation app.german (provider = icu, locale = 'de-u-co-phonebk');
create table app.people (id int primary key, name text collate app.german, city varchar(20) collate "sv-x-icu");
create index people_city_idx on app.people (city collate "de-x-icu");
create index tickets_account_idx on app.tickets (account_id);
create unique index tickets_title_idx on app.tickets (lower(title)) where body is not null;
create view app.open_tickets as select t.id, t.title, a.code from app.tickets t join app.accounts a on a.id = t.account_id where t.body is not null;
create materialized view app.counts as select account_id, count(*) as n from app.tickets group by account_id;
create function app.bump(n int) returns int language sql immutable as 'select n + 1';
create function app.stamp() returns trigger language plpgsql as $$ begin new.body := coalesce(new.body, 'stamped'); return new; end $$;
create trigger tickets_stamp before insert on app.tickets for each row execute function app.stamp();
create function app.two(a int, b text default 'x') returns table(n int, t text) language sql as $$ select a, b $$;
create procedure app.noop(x int) language sql as 'select 1';
create table app.tokens (id uuid primary key default gen_random_uuid(), owner_id uuid, label text);
insert into app.accounts (code, balance, tags, status) values ('A1', 10.50, '{x,y}', 'open'), ('B2', 0, default, default);
insert into app.tickets (account_id, title, body, mood) values (1, 'first', null, 'ok'), (1, 'second', 'has body', 'sad'), (2, 'third one', 'more', null);
insert into app.numbered (label) values ('a'), ('b');
insert into app.people values (1, 'Müller', 'Åre'), (2, 'Mueller', 'Ystad');
insert into app.priced (net, tax) values (10, 2.5), (20, 0);
insert into app.badges values (1, 'A1'), (2, 'B2'), (3, null);
insert into app.files values (1, 'a', '\xdeadbeef', sha256('a')), (2, 'empty', '', null), (3, 'nulls', default, null);
insert into app.tokens (id, owner_id, label) values ('a0eebc99-9c0b-4ef8-bb6d-6bb9bd380a11', 'B0EEBC99-9C0B-4EF8-BB6D-6BB9BD380A12', 'first');
refresh materialized view app.counts;
comment on schema app is 'the app';
comment on table app.accounts is 'who pays';
comment on column app.accounts.code is 'public code';
comment on view app.open_tickets is 'tickets to work on';
comment on materialized view app.counts is 'tickets by account';
comment on index app.tickets_title_idx is 'lookup by title';
comment on constraint tickets_account_id_fkey on app.tickets is 'the owner of a ticket';
comment on sequence app.ticket_no is 'ticket numbers';
